typedef unsigned int uint32;

template<class T> class my_allocator;

template<class T, class Alloc = my_allocator<T> >
class vector
{
public:
  typedef T* iterator;
  iterator start;
  iterator finish;
  iterator end_of_storage;

  iterator begin() { return start; }
  iterator end() { return finish; }
  void _M_insert_aux(iterator, const T&);
  void push_back(const T& value)
  {
    if (finish != end_of_storage)
    {
      *finish = value;
      ++finish;
    }
    else
      _M_insert_aux(finish, value);
  }
};

template<class Iterator, class T>
Iterator find(Iterator first, Iterator last, const T& value);

enum entity_flavor_t
{
  ENTITY_ENTITY = 1,
  ENTITY_MARKER = 2,
  ENTITY_MIC = 3,
  ENTITY_LIGHT_SOURCE = 4,
  ENTITY_CONGLOMERATE = 10
};

enum visual_rep_type
{
  VISREP_PMESH = 0
};

enum entity_flag
{
  EFLAG_ACTIVE = 0x00020000
};

class terrain;

class visual_rep
{
public:
  visual_rep_type type;
  visual_rep_type get_type() const { return type; }
};

class vr_pmesh : public visual_rep
{
public:
  virtual bool is_uv_animated() const;
};

class entity
{
public:
  virtual void compute_sector(terrain&, bool);
  virtual visual_rep* get_vrep() const;
  virtual void frame_done();

  char pad0[108];
  uint32 flags;
  entity_flavor_t flavor;

  entity_flavor_t get_flavor() const { return flavor; }
  void set_flag(uint32 f, bool set)
  {
    if (set)
      flags |= f;
    else
      flags &= ~f;
  }
};

void check_po(entity*);

class world_dynamics_system
{
public:
  char pad0[100];
  vector<entity*> entities;
  char pad1[124];
  terrain* the_terrain;
  char pad2[68];
  bool loading_from_scn_file;

  void add_dynamic_instanced_entity(entity*);
};

void world_dynamics_system::add_dynamic_instanced_entity(entity* e)
{
  vector<entity*>::iterator it;
  it = find(entities.begin(), entities.end(), (entity*)0);
  if (it == entities.end())
  {
    entities.push_back(e);
  }
  else
    *it = e;
  check_po(e);
  e->compute_sector(*the_terrain, loading_from_scn_file);
  switch (e->get_flavor())
  {
    case ENTITY_ENTITY:
    case ENTITY_MARKER:
    case ENTITY_MIC:
    case ENTITY_LIGHT_SOURCE:
    case ENTITY_CONGLOMERATE:
    {
      visual_rep* vrep = e->get_vrep();
      if (!(vrep && vrep->get_type() == VISREP_PMESH
            && ((vr_pmesh*)vrep)->is_uv_animated()))
        e->set_flag(EFLAG_ACTIVE, false);
      break;
    }
    default:
      break;
  }
  e->frame_done();
}
